'use strict';
// demo/index-bgp-lp.html is generated by demo/build-replay-bgp.js from demo/bgp-lp/ (page template,
// topology, frame*.json, replay.json). Rebuild it in memory and check it matches the committed page.
const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { build, DEFAULT_CONFIG } = require('../demo/build-replay-bgp.js');

const PAGE = path.join(__dirname, '..', 'demo', 'index-bgp-lp.html');

// pull the FRAMES / LABELS / CAPS arrays out of a built replay page
function embedded(html) {
  function arr(name, next) {
    const start = html.indexOf('var ' + name + '=');
    assert.ok(start >= 0, 'no ' + name + ' in page');
    const from = start + name.length + 5;
    const end = html.indexOf(next, from);
    assert.ok(end > from, 'no end of ' + name);
    return JSON.parse(html.slice(from, end));
  }
  return { frames: arr('FRAMES', ';var LABELS='), labels: arr('LABELS', ';var CAPS='), caps: arr('CAPS', ';var cap=') };
}

test('rebuilt BGP LocalPref page embeds the same frames, labels and captions as the committed page', () => {
  const committed = embedded(fs.readFileSync(PAGE, 'utf8'));
  const r = build();
  const rebuilt = embedded(r.html);
  assert.strictEqual(committed.frames.length, 4);
  assert.deepStrictEqual(rebuilt.frames, committed.frames);
  assert.strictEqual(JSON.stringify(rebuilt.frames), JSON.stringify(committed.frames));   // same key order and numbers too
  assert.deepStrictEqual(rebuilt.labels, committed.labels);
  assert.deepStrictEqual(rebuilt.caps, committed.caps);
  assert.strictEqual(path.resolve(r.output), path.resolve(PAGE));
});

test('frame files in demo/bgp-lp are the frames embedded in the committed page', () => {
  const committed = embedded(fs.readFileSync(PAGE, 'utf8'));
  const cfg = JSON.parse(fs.readFileSync(DEFAULT_CONFIG, 'utf8'));
  const files = cfg.frames.map((f) => JSON.parse(fs.readFileSync(path.join(path.dirname(DEFAULT_CONFIG), f.file), 'utf8')));
  assert.deepStrictEqual(files, committed.frames);
});

test('committed BGP LocalPref page is exactly what the builder writes', () => {
  const r = build();
  assert.strictEqual(r.html, fs.readFileSync(PAGE, 'utf8'), 'demo/index-bgp-lp.html is out of date: run node demo/build-replay-bgp.js');
  assert.ok(!/\{\{/.test(r.html), 'template placeholder left in page');
});

test('recorded text cannot end the replay <script> early', () => {
  const src = path.dirname(DEFAULT_CONFIG);
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'nx-bgp-build-'));
  try {
    const cfg = JSON.parse(fs.readFileSync(DEFAULT_CONFIG, 'utf8'));
    for (const f of ['page.html.tmpl', 'topo.json', cfg.frames[0].file]) fs.copyFileSync(path.join(src, f), path.join(dir, f));
    cfg.frames = [{ file: cfg.frames[0].file, label: 'x</script><b>', caption: '<!-- y' }];
    cfg.output = 'out.html';
    fs.writeFileSync(path.join(dir, 'replay.json'), JSON.stringify(cfg));
    const html = build(path.join(dir, 'replay.json')).html;
    assert.ok(!html.includes('x</script>') && !html.includes('<!-- y'));
    const e = embedded(html);
    assert.deepStrictEqual(e.labels, ['x</script><b>']);
    assert.deepStrictEqual(e.caps, ['<!-- y']);
    assert.ok(!fs.existsSync(path.join(dir, 'out.html')), 'build() must not write the page');
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
